import{_ as o,a0 as u,w as a,s as p,ao as s,I as l,x as e,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"BLUI：創建遊戲 UI 的簡單方法 | LCTT x X-CMD","titleTemplate":false,"description":"BLUI：創建遊戲 UI 的簡單方法 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BLUI：創建遊戲 UI 的簡單方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BLUI：創建遊戲 UI 的簡單方法 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180615 BLUI- An easy way to create game UI","title":"BLUI：創建遊戲 UI 的簡單方法","tag":"201807","desc":""},"relativePath":"201807/20180615 BLUI- An easy way to create game UI.md","filePath":"[post].md"}'),m={name:"201807/20180615 BLUI- An easy way to create game UI.md"};function I(d,t,U,g,L,b){const n=u("Link");return a(),p("div",null,[t[28]||(t[28]=s('<h1 id="blui-創建遊戲-ui-的簡單方法" tabindex="-1">BLUI：創建遊戲 UI 的簡單方法 <a class="header-anchor" href="#blui-創建遊戲-ui-的簡單方法" aria-label="Permalink to “BLUI：創建遊戲 UI 的簡單方法”">​</a></h1><blockquote><p>開源遊戲開發插件運行虛幻引擎的用户使用基於 Web 的編程方式創建獨特的用户界面元素。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/gaming_plugin_blui_screenshot.jpg?itok=91nnYCt_" alt=""></p><p>遊戲開發引擎在過去幾年中變得越來越易於​​使用。像 Unity 這樣一直免費使用的引擎，以及最近從基於訂閲的服務切換到免費服務的<ruby>虛幻引擎<rt>Unreal Engine</rt></ruby>，允許獨立開發者使用 AAA 發行商相同達到行業標準的工具。雖然這些引擎都不是開源的，但每個引擎都能夠促進其周圍的開源生態系統的發展。</p><p>這些引擎中可以包含插件以允許開發人員通過添加特定程序來增強引擎的基本功能。這些程序的範圍可以從簡單的資源包到更復雜的事物，如人工智能 （AI） 集成。這些插件來自不同的創作者。有些是由引擎開發工作室和有些是個人提供的。後者中的很多是開源插件。</p><h3 id="什麼是-blui" tabindex="-1">什麼是 BLUI？ <a class="header-anchor" href="#什麼是-blui" aria-label="Permalink to “什麼是 BLUI？”">​</a></h3>',6)),l("p",null,[t[1]||(t[1]=e("作為獨立遊戲開發工作室的一員，我體驗到了在專有遊戲引擎上使用開源插件的好處。Aaron Shea 開發的一個開源插件 ",-1)),i(n,{href:"https://github.com/AaronShea/BLUI"},{default:r(()=>[...t[0]||(t[0]=[e("BLUI",-1)])]),_:1}),t[2]||(t[2]=e(" 對我們團隊的開發過程起到了重要作用。它允許我們使用基於 Web 的編程（如 HTML/CSS 和 JavaScript）創建用户界面 （UI） 組件。儘管",-1)),t[3]||(t[3]=l("ruby",null,[e("虛幻引擎"),l("rt",null,"Unreal Engine")],-1)),t[4]||(t[4]=e("（我們選擇的引擎）有一個實現了類似目的的內置 UI 編輯器，我們也選擇使用這個開源插件。我們選擇使用開源替代品有三個主要原因：它們的可訪問性、易於實現以及伴隨的開源程序活躍的、支持性好的在線社區。",-1))]),t[29]||(t[29]=l("p",null,"在虛幻引擎的最早版本中，我們在遊戲中創建 UI 的唯一方法是通過引擎的原生 UI 集成，使用 Autodesk 的 Scaleform 程序，或通過在虛幻社區中傳播的一些選定的基於訂閲的虛幻引擎集成。在這些情況下，這些解決方案要麼不能為獨立開發者提供有競爭力的 UI 解決方案，對於小型團隊來説太昂貴，要麼只能為大型團隊和 AAA 開發者提供。",-1)),l("p",null,[t[6]||(t[6]=e("在商業產品和虛幻引擎的原生整合失敗後，我們向獨立社區尋求解決方案。我們在那裏發現了 BLUI。它不僅與虛幻引擎無縫集成，而且還保持了一個強大且活躍的社區，經常推出更新並確保獨立開發人員可以輕鬆訪問文檔。BLUI 使開發人員能夠將 HTML 文件導入虛幻引擎，並在程序內部對其進行編程。這使得通過 web 語言創建的 UI 能夠集成到遊戲的代碼、資源和其他元素中，並擁有所有 HTML、CSS、Javascript 和其他網絡語言的能力。它還為開源 ",-1)),i(n,{href:"https://bitbucket.org/chromiumembedded/cef"},{default:r(()=>[...t[5]||(t[5]=[e("Chromium Embedded Framework",-1)])]),_:1}),t[7]||(t[7]=e(" 提供全面支持。",-1))]),t[30]||(t[30]=s('<h3 id="安裝和使用-blui" tabindex="-1">安裝和使用 BLUI <a class="header-anchor" href="#安裝和使用-blui" aria-label="Permalink to “安裝和使用 BLUI”">​</a></h3><p>使用 BLUI 的基本過程包括首先通過 HTML 創建 UI。開發人員可以使用任何工具來實現此目的，包括<ruby>自舉<rt>bootstrapped</rt></ruby> JavaScript 代碼、外部 API 或任何資料庫代碼。一旦這個 HTML 頁面完成，你可以像安裝任何虛幻引擎插件那樣安裝它，並加載或創建一個項目。項目加載後，你可以將 BLUI 函數放在虛幻引擎 UI 圖紙中的任何位置，或者通過 C++ 進行硬編碼。開發人員可以通過其 HTML 頁面調用函數，或使用 BLUI 的內部函數輕鬆更改變量。</p><p><img src="https://opensource.com/sites/default/files/uploads/blui_gaming_plugin-integratingblui.png" alt="Integrating BLUI into Unreal Engine 4 blueprints" title="Integrating BLUI into Unreal Engine 4 blueprints"></p><p><em>將 BLUI 集成到虛幻 4 圖紙中。</em></p><p>在我們當前的項目中，我們使用 BLUI 將 UI 元素與遊戲中的音軌同步，為遊戲機制的節奏方面提供視覺反饋。將定製引擎編程與 BLUI 插件集成很容易。</p><p><img src="https://opensource.com/sites/default/files/uploads/blui_gaming_plugin-syncui.png" alt="Using BLUI to sync UI elements with the soundtrack." title="Using BLUI to sync UI elements with the soundtrack."></p><p><em>使用 BLUI 將 UI 元素與音軌同步。</em></p>',7)),l("p",null,[t[10]||(t[10]=e("通過 BLUI GitHub 頁面上的",-1)),i(n,{href:"https://github.com/AaronShea/BLUI/wiki"},{default:r(()=>[...t[8]||(t[8]=[e("文檔",-1)])]),_:1}),t[11]||(t[11]=e("，將 BLUI 集成到虛幻 4 中是一個輕鬆的過程。還有一個由支持虛幻引擎開發人員組成的",-1)),i(n,{href:"https://forums.unrealengine.com/community/released-projects/29036-blui-open-source-html5-js-css-hud-ui"},{default:r(()=>[...t[9]||(t[9]=[e("論壇",-1)])]),_:1}),t[12]||(t[12]=e("，他們樂於詢問和回答關於插件以及實現該工具時出現的任何問題。",-1))]),t[31]||(t[31]=l("h3",{id:"開源優勢",tabindex:"-1"},[e("開源優勢 "),l("a",{class:"header-anchor",href:"#開源優勢","aria-label":"Permalink to “開源優勢”"},"​")],-1)),t[32]||(t[32]=l("p",null,"開源插件可以在專有遊戲引擎的範圍內擴展創意。他們繼續降低進入遊戲開發的障礙，並且可以產生前所未有的遊戲內的機制和資源。隨着對專有遊戲開發引擎的訪問持續增長，開源插件社區將變得更加重要。不斷增長的創造力必將超過專有軟件，開源代碼將會填補這些空白，並促進開發真正獨特的遊戲。而這種新穎性正是讓獨立遊戲如此美好的原因！",-1)),t[33]||(t[33]=l("hr",null,null,-1)),l("p",null,[t[14]||(t[14]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/18/6/blui-game-development-plugin"},{default:r(()=>[...t[13]||(t[13]=[e("https://opensource.com/article/18/6/blui-game-development-plugin",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/uwikaiddi"},{default:r(()=>[...t[15]||(t[15]=[e("Uwana lkaiddi",-1)])]),_:1}),t[20]||(t[20]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[16]||(t[16]=[e("lujun9972",-1)])]),_:1}),t[21]||(t[21]=e(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:r(()=>[...t[17]||(t[17]=[e("geekpi",-1)])]),_:1}),t[22]||(t[22]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[18]||(t[18]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[25]||(t[25]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[23]||(t[23]=[e("LCTT",-1)])]),_:1}),t[26]||(t[26]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:r(()=>[...t[24]||(t[24]=[e("Linux中國",-1)])]),_:1}),t[27]||(t[27]=e(" 榮譽推出",-1))])])}const A=o(m,[["render",I]]);export{T as __pageData,A as default};
